std::vector<double> result(cols_);
// Drive the per-column outputs with std::transform. The input range is
// a list of column indices [0, 1, ..., cols_-1]; the output is the
// sum of each column, computed by std::accumulate over the column
// entries. The cache access pattern is the same as the hand-rolled
// version (stride == cols_ doubles) - this is still the slow path -
// but the structure now uses the standard algorithms.
std::vector<std::size_t> columns(cols_);
std::iota(columns.begin(), columns.end(), std::size_t{0});
std::transform(columns.begin(), columns.end(), result.begin(),
               [this](std::size_t c) {
                   std::vector<double> col(rows_);
                   for (std::size_t r = 0; r < rows_; ++r) {
                       col[r] = at(r, c);
                   }
                   return std::accumulate(col.begin(), col.end(), 0.0);
               });

